            scwin.div_submit.setStyle("display", "none");
            scwin.div_close.setStyle("display", "");
            await $c.win.alert('현재의 발행기관은 주권상장법인입니다. \n주권상장법인은 발행기관변경신청을 받지 않습니다.');
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf05401.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_checkForm_onclick
 * @description btn_checkForm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_checkForm_onclick = function(e){
    try {
        scwin.check_form()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05401.btn_checkForm_onclick' }); }
};

/**
 * @method
 * @name btn_selfClose_onclick
 * @description btn_selfClose 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_selfClose_onclick = async function(e){
    try {
        await scwin.self_close()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf05401.btn_selfClose_onclick' }); }
};

/**
 * @method
 * @name btn_selfClose_2_onclick
 * @description btn_selfClose_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_selfClose_2_onclick = async function(e){
    try {
        await scwin.self_close()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf05401.btn_selfClose_2_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name check_form
 * @description check form 처리
 * @returns {void}
 * @hidden N
 */
scwin.check_form = function () {
    ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : scwin.openerScwin()).parent).go_modify();
    $c.win.closePopup();
};

/**
 * @method
 * @name self_close
 * @description self close 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.self_close = async function () {
    if (await $c.win.confirm("신청을 취소하시겠습니까?")) {
        $c.win.closePopup();
    }
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
